bool ValueSetConstraint::validate(const std::string& value, ValueType type) const {
  // Handle exclusions first
  if (excludedValueType.has_value() && excludedValueType.value() == type) {
    return false;
  }
  if (!excludedIris.empty() && excludedIris.contains(value)) {
    return false;
  }

  // Normal validation
  bool normalResult = /* existing validation logic */;

  // Apply negation if needed
  return (negation == NegationOperator::NOT) ? !normalResult : normalResult;
}

LogicalExpression_validate.pseudocode:
bool LogicalExpression::validate(const std::string& value, ValueType type) const {
  if (op == LogicalOperator::AND) {
    for (const auto& operand : operands) {
      bool result = std::visit([&](auto&& constraint) {
        return constraint.validate(value, type);
      }, operand.constraint);

      if (operand.negation == NegationOperator::NOT) result = !result;
      if (!result) return false;  // Short-circuit
    }
    return true;
  } else {  // OR
    for (const auto& operand : operands) {
      bool result = std::visit([&](auto&& constraint) {
        return constraint.validate(value, type);
      }, operand.constraint);

      if (operand.negation == NegationOperator::NOT) result = !result;
      if (result) return true;  // Short-circuit
    }
    return false;
  }
}

